<script setup lang="ts">
const date=ref(new Date().toISOString().slice(0,10)); const to=ref(date.value); const bookings=ref<any[]>([]); const error=ref(''); const loading=ref(false)
async function load(){loading.value=true;error.value='';try{const r:any=await $fetch('/api/admin/bookings',{query:{from:date.value,to:to.value}});bookings.value=r.bookings}catch(e:any){error.value=e?.statusCode===401?'Нужно войти в аккаунт.':e?.statusCode===403?'Нет доступа администратора.':e?.statusCode===503?'База данных временно недоступна.':'Не удалось загрузить записи.'}finally{loading.value=false}}
async function status(id:string,status:string){await $fetch(`/api/admin/bookings/${id}`,{method:'PATCH',body:{status}});await load()}
await load()
</script>
<template><div><div class="flex flex-wrap items-end justify-between gap-4"><div><h1 class="text-3xl font-bold">Админка</h1><p class="text-slate-600">Управление записями</p></div><div class="flex gap-2"><input v-model="date" type="date" class="rounded-xl border p-2"><input v-model="to" type="date" class="rounded-xl border p-2"><button class="rounded-xl bg-slate-900 px-4 py-2 text-white" @click="load">Обновить</button></div></div><p v-if="error" class="mt-4 rounded-xl bg-red-50 p-3 text-red-700">{{error}}</p><div class="mt-6 overflow-x-auto rounded-2xl border bg-white"><table class="w-full min-w-[800px] text-left"><thead class="border-b bg-slate-50"><tr><th class="p-3">Дата</th><th class="p-3">Время</th><th class="p-3">Клиент</th><th class="p-3">Авто</th><th class="p-3">Цена</th><th class="p-3">Статус</th><th class="p-3">Действие</th></tr></thead><tbody><tr v-for="b in bookings" :key="b.id" class="border-b"><td class="p-3">{{b.booking_date}}</td><td class="p-3">{{String(b.booking_time).slice(0,5)}}</td><td class="p-3">{{b.name}}<br><span class="text-xs text-slate-500">{{b.phone}}</span></td><td class="p-3">{{b.make}} {{b.model}}</td><td class="p-3">{{(b.price_cents/100).toFixed(0)}} €</td><td class="p-3">{{b.status}}</td><td class="p-3"><select class="rounded-lg border p-2" :value="b.status" @change="status(b.id,($event.target as HTMLSelectElement).value)"><option>pending</option><option>confirmed</option><option>completed</option><option>cancelled_admin</option><option>no_show</option></select></td></tr></tbody></table><p v-if="!loading&&!bookings.length" class="p-6 text-slate-500">Записей нет.</p></div></div></template>
